/** Decoded once per isolate; the renderer asks for it on every report. */
let decoded: Buffer | null = null;

export function logoBytes(): Buffer {
  if (decoded === null) {
    decoded = Buffer.from(LOGO_PNG_BASE64, 'base64');
  }
  return decoded;
}
